813	    // ─── TSType → CollectedType ───────────────────────────────────────────────
814	
815	    pub(super) fn ts_type_to_collected<'a>(&mut self, ty: &TSType<'a>) -> CollectedType {
816	        self.ts_type_to_collected_at_depth(ty, 0)
817	    }
818	
819	    fn ts_type_to_collected_at_depth<'a>(&mut self, ty: &TSType<'a>, depth: u8) -> CollectedType {
820	        if depth > MAX_TYPE_COLLECT_DEPTH {
821	            use oxc_span::GetSpan;
822	            let span = ty.span();
823	            self.data.diagnostics.push(Diagnostic {
824	                severity: DiagnosticSeverity::Warning,
825	                message: format!(
826	                    "Type nesting exceeds maximum extractor recursion depth ({depth} > {MAX_TYPE_COLLECT_DEPTH})"
827	                ),
828	                file: Some(self.file_path.to_string()),
829	                line: None,
830	                column: None,
831	                help: Some("This may indicate a deeply chained conditional or mapped type.".into()),
832	                code: DiagnosticCode::MaxDepthExceeded,
833	                affects: Vec::new(),
834	            });
835	            let raw = self.source[span.start as usize..span.end as usize].to_owned();
836	            return CollectedType::Raw(raw);
837	        }
838	        match ty {
839	            TSType::TSStringKeyword(_) => CollectedType::String,
840	            TSType::TSNumberKeyword(_) => CollectedType::Number,
841	            TSType::TSBooleanKeyword(_) => CollectedType::Boolean,
842	            TSType::TSNullKeyword(_) => CollectedType::Null,
843	            TSType::TSUndefinedKeyword(_) => CollectedType::Undefined,
844	            TSType::TSAnyKeyword(_) => CollectedType::Any,
845	            TSType::TSNeverKeyword(_) => CollectedType::Never,
846	            TSType::TSUnknownKeyword(_) => CollectedType::Unknown,
847	            TSType::TSVoidKeyword(_) => CollectedType::Void,
848	            TSType::TSBigIntKeyword(_) => CollectedType::BigInt,
849	            TSType::TSSymbolKeyword(_) => CollectedType::Symbol,
850	            TSType::TSObjectKeyword(_) => CollectedType::Named { name: "object".into(), args: vec![] },
851	
852	            TSType::TSLiteralType(lit) => match &lit.literal {
853	                TSLiteral::StringLiteral(s) => CollectedType::StringLiteral(js_text::lossy(s.value).as_ref().into()),
854	                TSLiteral::NumericLiteral(n) => CollectedType::NumberLiteral(n.value),
855	                TSLiteral::BooleanLiteral(b) => CollectedType::BoolLiteral(b.value),
856	                TSLiteral::UnaryExpression(u) => {
857	                    // Handle negative numbers: -1
858	                    let raw = self.source[u.span.start as usize..u.span.end as usize].to_owned();
859	                    CollectedType::Raw(raw)
860	                }
861	                _ => CollectedType::Raw(self.source[lit.span.start as usize..lit.span.end as usize].to_owned()),
862	            },
863	
864	            TSType::TSTypeReference(tr) => {
865	                let name: CompactString = self.ts_type_name_str(&tr.type_name).into();
866	                let args = tr
867	                    .type_arguments
868	                    .as_ref()
869	                    .map(|ta| ta.params.iter().map(|p| self.ts_type_to_collected_at_depth(p, depth + 1)).collect())
870	                    .unwrap_or_default();
871	                CollectedType::Named { name, args }
872	            }
873	
874	            TSType::TSTypeQuery(q) => {
875	                let name = self.ts_type_query_name(q);
876	                CollectedType::TypeOf(name.into())
877	            }
878	
879	            TSType::TSUnionType(u) => {
880	                let members: Vec<CollectedType> =
881	                    u.types.iter().map(|t| self.ts_type_to_collected_at_depth(t, depth + 1)).collect();
882	                CollectedType::Union(members)
883	            }
884	
885	            TSType::TSIntersectionType(i) => {
886	                let members: Vec<CollectedType> =
887	                    i.types.iter().map(|t| self.ts_type_to_collected_at_depth(t, depth + 1)).collect();
888	                CollectedType::Intersection(members)
889	            }
890	
891	            TSType::TSArrayType(a) => {
892	                CollectedType::Array(Box::new(self.ts_type_to_collected_at_depth(&a.element_type, depth + 1)))
893	            }
894	
895	            TSType::TSTupleType(t) => {
896	                let members: Vec<CollectedType> =
897	                    t.element_types.iter().map(|el| self.ts_tuple_element_to_collected(el, depth + 1)).collect();
898	                CollectedType::Tuple(members)
899	            }
900	
901	            TSType::TSTypeLiteral(lit) => {
902	                let callables = lit
903	                    .members
904	                    .iter()
905	                    .filter(|member| {
906	                        matches!(
907	                            member,
908	                            TSSignature::TSCallSignatureDeclaration(_)
909	                                | TSSignature::TSConstructSignatureDeclaration(_)
910	                        )
911	                    })
912	                    .count();
913	                if callables > 0 {
914	                    // `{ (a: string): number }` is a function type. Anything else with a call or construct signature
915	                    // (overloads, a callable that also has properties) has no `Function` form, and an object of its
916	                    // fields would drop the signatures without a word, so it is kept as written and degrades.
917	                    match lit.members.as_slice() {
918	                        [TSSignature::TSCallSignatureDeclaration(call)] => {
919	                            let (params, param_names, param_kinds) =
920	                                collect_params(&call.params, |t| self.ts_type_to_collected_at_depth(t, depth + 1));
