1015	            TSType::TSTypeOperatorType(op) => match op.operator {
1016	                TSTypeOperatorOperator::Keyof => {
1017	                    CollectedType::KeyOf(Box::new(self.ts_type_to_collected_at_depth(&op.type_annotation, depth + 1)))
1018	                }
1019	                TSTypeOperatorOperator::Readonly => CollectedType::Readonly(Box::new(
1020	                    self.ts_type_to_collected_at_depth(&op.type_annotation, depth + 1),
1021	                )),
1022	                TSTypeOperatorOperator::Unique => self.ts_type_to_collected_at_depth(&op.type_annotation, depth + 1),
1023	            },
1024	
1025	            TSType::TSInferType(i) => {
1026	                let raw = self.source[i.span.start as usize..i.span.end as usize].to_owned();
1027	                CollectedType::Raw(raw)
1028	            }
1029	
1030	            // Anything else: capture raw source text as fallback
1031	            _ => {
1032	                use oxc_span::GetSpan;
1033	                let span = ty.span();
1034	                let raw = self.source[span.start as usize..span.end as usize].to_owned();
1035	                CollectedType::Raw(raw)
1036	            }
1037	        }
1038	    }
