1040	    /// Convert a `TSTupleElement` (which is a superset of `TSType`) to a `CollectedType`.
1041	    ///
1042	    /// TSTupleElement inherits all TSType variants and adds TSOptionalType and TSRestType.
1043	    pub(super) fn ts_tuple_element_to_collected<'a>(&mut self, el: &TSTupleElement<'a>, depth: u8) -> CollectedType {
1044	        match el {
1045	            TSTupleElement::TSOptionalType(o) => {
1046	                // T? in tuple → Union([T, Undefined])
1047	                let inner = self.ts_type_to_collected_at_depth(&o.type_annotation, depth + 1);
1048	                CollectedType::Union(vec![inner, CollectedType::Undefined])
1049	            }
1050	            TSTupleElement::TSRestType(r) => {
1051	                // ...T[] in tuple → Array(T)
1052	                CollectedType::Array(Box::new(self.ts_type_to_collected_at_depth(&r.type_annotation, depth + 1)))
1053	            }
1054	            // A labelled member `name: T` or `name?: T` is its type; an optional marker is not preserved.
1055	            TSTupleElement::TSNamedTupleMember(named) => {
1056	                self.ts_tuple_element_to_collected(&named.element_type, depth + 1)
1057	            }
1058	            // The remaining variants are the plain `TSType`s the element inherits.
1059	            other => match other.as_ts_type() {
1060	                Some(ty) => self.ts_type_to_collected_at_depth(ty, depth + 1),
1061	                None => {
1062	                    use oxc_span::GetSpan;
1063	                    let span = other.span();
1064	                    CollectedType::Raw(self.source[span.start as usize..span.end as usize].to_owned())
1065	                }
1066	            },
1067	        }
1068	    }
