1072	        // Capture the source text of the expression name
1073	        use oxc_span::GetSpan;
1074	        let span = q.expr_name.span();
1075	        self.source[span.start as usize..span.end as usize].to_owned()
1076	    }
1077	
1078	    pub(super) fn ts_signature_to_object_field<'a>(
