// ─── Helpers ──────────────────────────────────────────────────────────────────

pub(super) fn is_pascal_case(s: &str) -> bool {
    let mut chars = s.chars();
    chars.next().is_some_and(|c| c.is_uppercase())
}

/// Whether `name` is written as a constant, `MENU_OPTIONS` or `ORIGIN`: more than one letter and none lowercase. Such a
/// binding is not reported as a component candidate that failed to qualify; a rule that does match it still maps it.
pub(super) fn is_constant_name(name: &str) -> bool {
    name.chars().count() > 1 && !name.chars().any(char::is_lowercase)
}

/// The names a function type declares as its own type parameters (`<T, U>`).
fn type_param_names(declaration: Option<&TSTypeParameterDeclaration>) -> Vec<CompactString> {
    declaration
        .map(|d| d.params.iter().map(|p| CompactString::from(p.name.name.as_str())).collect())
        .unwrap_or_default()
}

/// A signature's parameters as collected: their types, simple names and kinds, with the rest parameter last.
/// OXC keeps `...rest` apart from the other parameters, and its annotation is the array type as written.
fn collect_params(
    params: &FormalParameters,
    mut convert: impl FnMut(&TSType) -> CollectedType,
) -> (Vec<CollectedType>, Vec<Option<CompactString>>, Vec<ParamKind>) {
    let mut types = Vec::with_capacity(params.items.len() + 1);
    let mut names = Vec::with_capacity(params.items.len() + 1);
    let mut kinds = Vec::with_capacity(params.items.len() + 1);
    for p in &params.items {
        types.push(p.type_annotation.as_ref().map(|ta| convert(&ta.type_annotation)).unwrap_or(CollectedType::Any));
        names.push(binding_pattern_name(&p.pattern));
        kinds.push(ParamKind::new(p.optional, false));
    }
    if let Some(rest) = &params.rest {
        types.push(rest.type_annotation.as_ref().map(|ta| convert(&ta.type_annotation)).unwrap_or(CollectedType::Any));
        names.push(binding_pattern_name(&rest.rest.argument));
        kinds.push(ParamKind::Rest);
    }
    (types, names, kinds)
}

/// A parameter's simple identifier name, if it has one (not a destructured pattern).
fn binding_pattern_name(pattern: &BindingPattern) -> Option<CompactString> {
    match pattern {
        BindingPattern::BindingIdentifier(id) => Some(id.name.as_str().into()),
        _ => None,
    }
}

/// Get the declared name from a Declaration node.
pub(super) fn declaration_name<'a>(decl: &Declaration<'a>) -> Option<&'a str> {
    match decl {
        Declaration::VariableDeclaration(vd) => vd.declarations.first().and_then(|d| match &d.id {
            BindingPattern::BindingIdentifier(id) => Some(id.name.as_str()),
            _ => None,
        }),
        Declaration::FunctionDeclaration(f) => f.id.as_ref().map(|id| id.name.as_str()),
        Declaration::ClassDeclaration(c) => c.id.as_ref().map(|id| id.name.as_str()),
        Declaration::TSTypeAliasDeclaration(ta) => Some(ta.id.name.as_str()),
        Declaration::TSInterfaceDeclaration(iface) => Some(iface.id.name.as_str()),
        Declaration::TSEnumDeclaration(e) => Some(e.id.name.as_str()),
        Declaration::TSNamespaceDeclaration(ns) => Some(ns.id.name.as_str()),
        Declaration::TSExternalModuleDeclaration(m) => m.id.value.as_str(),
        _ => None,
    }
}

