143	                return PropType::Named { name: name.trim().into(), args: vec![] };
144	            }
145	            // Double-quoted string literal: `"button"` → StringLiteral.
146	            if trimmed.starts_with('"') && trimmed.ends_with('"') && trimmed.len() >= 2 {
147	                return PropType::StringLiteral(trimmed[1..trimmed.len() - 1].to_owned());
148	            }
149	            // Single-quoted string literal: `'button'` → StringLiteral.
150	            if trimmed.starts_with('\'') && trimmed.ends_with('\'') && trimmed.len() >= 2 {
151	                return PropType::StringLiteral(trimmed[1..trimmed.len() - 1].to_owned());
152	            }
153	            // TypeScript primitive keywords — tuple elements come through Raw because
154	            // TSTupleElement falls through to source-text extraction for non-optional,
155	            // non-rest elements. Recognise keywords here so they emit the proper PropType.
156	            match trimmed {
157	                "string" => return PropType::String,
158	                "number" => return PropType::Number,
159	                "boolean" => return PropType::Boolean,
160	                "null" => return PropType::Null,
161	                "undefined" => return PropType::Undefined,
162	                "never" => return PropType::Never,
163	                "void" => return PropType::Void,
164	                "any" => return PropType::Any,
165	                "unknown" => return PropType::Unknown,
166	                _ => {}
167	            }
168	            // A plain identifier (possibly qualified) names a type; any other text is syntax the extractor did not
169	            // structure, so it degrades with a diagnostic instead of becoming a `Named` type called `[string]`.
170	            let is_identifier = trimmed.starts_with(|c: char| c.is_alphabetic() || c == '_' || c == '$')
171	                && trimmed.chars().all(|c| c.is_alphanumeric() || matches!(c, '_' | '$' | '.'));
172	            if is_identifier {
173	                PropType::Named { name: trimmed.into(), args: vec![] }
174	            } else {
175	                let diag = opaque_diagnostic("an unparsable raw type expression", ct, consuming_file);
176	                OpaqueDetail::give_up(state, s.clone(), OpaqueReason::UnsupportedExpression, diag)
177	            }
178	        }
179	    }
180	}
