17	/// Cycle-detecting entry point — see `ResolveState::named_in_progress`'s doc
18	/// comment for why this can't reuse chain.rs's permanent `visited` set or
19	/// mimic its clone-per-branch pattern. Delegates the actual resolution to
20	/// `resolve_named_uncycled` so every one of that function's many early
21	/// returns doesn't need to remember to remove the in-progress key itself.
22	#[allow(clippy::too_many_arguments)]
23	pub(super) fn resolve_named(
24	    name: &CompactString,
25	    args: &[CollectedType],
26	    consuming_file: &Utf8Path,
27	    ctx: &ResolutionContext,
28	    state: &mut ResolveState,
29	    depth: u8,
30	) -> PropType {
31	    // Structural arguments: their display form abbreviates object types to `{ ... }`, which collided distinct
32	    // instantiations into a false cycle.
33	    let visit_key: CompactString = {
34	        use std::hash::Hasher;
35	        let mut hasher = rustc_hash::FxHasher::default();
36	        args.iter().for_each(|arg| arg.structural_hash(&mut hasher));
37	        let site = state.declared_in.as_deref().and_then(DeclarationScope::local_key_suffix).unwrap_or_default();
38	        format!("{}:{}<{:x}>{site}", consuming_file, name, hasher.finish()).into()
39	    };
40	
41	    // The same reference resolves the same way in any state that answers the reads it made (`resolver::memo`), and
42	    // Chakra's style props name a few thousand distinct ones a million times.
43	    ctx.named_results.get_or_resolve(&visit_key, depth, state, None, |state| {
44	        if !state.enter_named(&visit_key) {
45	            state.diagnostics.push(Diagnostic {
46	                severity: DiagnosticSeverity::Info,
47	                message: format!(
48	                    "Circular type reference detected resolving '{}' in '{}' — stopping here to avoid infinite recursion",
49	                    name, consuming_file
50	                ),
51	                file: Some(consuming_file.to_string()),
52	                line: None,
53	                column: None,
54	                help: Some("This type (directly or indirectly) references itself.".into()),
55	                code: DiagnosticCode::CircularReference,
56	                affects: Vec::new(),
57	            });
58	            return OpaqueDetail::new(name.to_string(), OpaqueReason::DepthExceeded);
59	        }
60	
61	        let result = resolve_named_uncycled(name, args, consuming_file, ctx, state, depth);
62	        state.leave_named(&visit_key);
63	        result
64	    })
65	}
66	
67	#[allow(clippy::too_many_arguments)]
68	fn resolve_named_uncycled(
69	    name: &CompactString,
70	    args: &[CollectedType],
71	    consuming_file: &Utf8Path,
72	    ctx: &ResolutionContext,
73	    state: &mut ResolveState,
74	    depth: u8,
75	) -> PropType {
76	    // `depth` counts how deeply one type expression nests; an alias body starts again at 0, since the alias is a
77	    // declaration of its own (csstype's `Property.X` is four aliases deep under a prop already 15 levels down). What
78	    // bounds the hops between declarations, and the expansion of a generic that never repeats, is the names in progress.
79	    if super::past_max_depth(state, depth) || state.named_in_progress.len() > MAX_NAMED_NESTING {
80	        let diag = super::max_depth_diagnostic(&format!("named type '{}'", name), consuming_file);
81	        return OpaqueDetail::give_up(state, name.to_string(), OpaqueReason::DepthExceeded, diag);
82	    }
83	
84	    // A reference marked as a declaration's is looked up as one, whatever type parameter is in scope under its name.
85	    let declared_name;
86	    let (name, as_declaration) = match name.strip_suffix(DECLARATION_MARK) {
87	        Some(bare) => {
88	            declared_name = CompactString::from(bare);
89	            (&declared_name, true)
90	        }
91	        None => (name, false),
92	    };
93	
94	    // ── 0. A type parameter in scope shadows any declaration of the same name ──
95	    if !as_declaration && args.is_empty() && state.has_type_param(name) {
96	        return PropType::Named { name: unmarked(name).into(), args: Vec::new() };
97	    }
98	
99	    // ── 1. React builtin check ────────────────────────────────────────────────
100	    let lookup_name = name.strip_prefix("React.").unwrap_or(name.as_str());
101	    // React's meaning only for React's binding: a project's own `ReactNode` or `Ref` resolves as declared below.
102	    if react_types::is_react_builtin(lookup_name, &ctx.extra_builtins)
103	        && (ctx.extra_builtins.contains(lookup_name) || super::may_be_react_builtin(name, consuming_file, ctx))
104	    {
105	        return react_type_to_prop_type(name.as_str(), args, consuming_file, ctx, state, depth);
106	    }
107	
108	    // ── 2-5. Try the project's own source before a known-pattern shortcut ────
109	    // See `resolver::precedence` — the shared, single-source-of-truth order.
110	    let (canonical_file, canonical_name, declared) =
111	        super::precedence::find_declaration(name.as_str(), consuming_file, ctx, state);
112	    // The arguments of everything but an alias are resolved here; an alias's are resolved once, where its expansion
113	    // reads them, instead of here as well.
114	    let resolved_args: Vec<PropType> = if matches!(declared, Some(Declared::TypeAlias { .. })) {
115	        Vec::new()
116	    } else {
117	        args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect()
118	    };
119	    let matched = match declared {
120	        Some(Declared::TypeAlias { matched_key, alias }) => {
121	            Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias: *alias })
122	        }
123	        Some(Declared::Interface(iface)) => Some(super::precedence::SourceOrKnownMatch::Interface(iface)),
124	        None => resolve_known(name, &resolved_args, &ctx.global, &|n| ctx.enum_key_for(n, consuming_file))
125	            .map(super::precedence::SourceOrKnownMatch::Known),
126	    };
127	
128	    match matched {
129	        Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias }) => {
130	            // The call site's arguments replace the alias's declared parameters (`type Foo<TData> = ...` used as
131	            // `Foo<string>`). Parameters left unfilled stay expected, unexpandable placeholders, not unresolvable
132	            // types, so they are registered for step 7 below.
133	            let params = ctx.named_types.lookup_type_alias_params(&canonical_file, &matched_key);
134	            let defaults = ctx.named_types.lookup_type_param_defaults(&canonical_file, &matched_key);
135	            let outer_named_unevaluated = std::mem::take(&mut state.named_unevaluated);
136	            let caller_site = super::precedence::enter_alias_site(ctx, state, &canonical_file, &matched_key);
137	            // The alias's body is read under its own parameters that nothing replaces, never under the caller's: the
138	            // supplied arguments are the caller's names (`Id<Value>` over `type Value`), not the alias's parameters.
139	            let expanded = match params {
140	                Some(params) if !args.is_empty() || defaults.is_some() => {
141	                    expand_alias(&alias, params, defaults, args, consuming_file, &canonical_file, ctx, state, 0)
142	                }
143	                Some(params) => {
144	                    let alias =
145	                        super::substitute::substitute_alias(&alias, &super::substitute::unfilled_substitution(params));
146	                    let caller = state.enter_scope(TypeScope::default());
147	                    let expanded = resolve_type_alias_type(&alias, ctx, state, depth);
148	                    state.leave_scope(caller);
149	                    expanded
150	                }
151	                None => {
152	                    let caller = state.enter_scope(TypeScope::default());
153	                    let expanded = resolve_type_alias_type(&alias, ctx, state, 0);
154	                    state.leave_scope(caller);
155	                    expanded
156	                }
157	            };
158	            state.leave_declared_in(caller_site);
159	            let unevaluated = state.named_unevaluated || expanded.holds_unevaluated_type();
160	            state.named_unevaluated = outer_named_unevaluated || unevaluated;
161	            // Printed as its name when it can't be evaluated, or when a generic instantiation expands to a long union, as
162	            // TypeScript prints it; its arguments are then shown as far as they evaluate.
163	            let by_name = unevaluated || (!args.is_empty() && exceeds_expanded_size(&expanded));
164	            if matches!(expanded, PropType::Object(_)) || !by_name {
165	                return expanded;
166	            }
167	            let args: Vec<CollectedType> =
168	                args.iter().map(|arg| displayed_arg(arg, consuming_file, ctx, state, depth)).collect();
169	            return PropType::Named { name: name.clone(), args: args.iter().map(super::func::as_written).collect() };
170	        }
171	        Some(super::precedence::SourceOrKnownMatch::Interface(_)) => {
172	            // At the prop-TYPE level (not chain level), an interface name is returned as Named.
173	            // Full prop expansion only happens at the component level via resolve_props_chain.
174	            return PropType::Named { name: name.clone(), args: resolved_args };
175	        }
176	        Some(super::precedence::SourceOrKnownMatch::Known(result)) => {
177	            return match result {
178	                KnownPatternResult::Type(pt) => {
179	                    if let PropType::Opaque(detail) = &pt {
180	                        push_known_opaque_diagnostic(
181	                            &mut state.diagnostics,
182	                            detail.reason(),
183	                            name.as_str(),
184	                            consuming_file,
185	                        );
186	                    }
187	                    pt
188	                }
189	                KnownPatternResult::Alias { name: alias_name } => {
190	                    // Follow the alias through resolve_named.
191	                    let alias_ct = CollectedType::Named { name: alias_name.as_str().into(), args: vec![] };
192	                    resolve_collected_type(&alias_ct, consuming_file, ctx, state, depth + 1)
193	                }
194	                KnownPatternResult::Props(_) => {
195	                    // Props result at type level — surface as Named.
196	                    PropType::Named { name: name.clone(), args: resolved_args }
197	                }
198	            };
199	        }
200	        None => {}
201	    }
202	
203	    // A builtin name bound elsewhere whose binding didn't resolve (a re-export of React's type, a package not
204	    // installed): React's meaning is then a reported guess.
205	    if react_types::is_react_builtin(lookup_name, &ctx.extra_builtins) {
206	        state.diagnostics.push(super::builtin_fallback_diagnostic(name, consuming_file, ctx));
207	        return react_type_to_prop_type(name.as_str(), args, consuming_file, ctx, state, depth);
208	    }
209	
210	    // ── 6. Silent no-op for well-known unresolvable types ────────────────────
211	    // TypeScript built-in utility types, DOM element types, and React HTML
212	    // attribute types all appear as prop types in real-world .d.ts files but
213	    // cannot be expanded without a type-checker. Return Named silently.
214	    let bare = name.strip_prefix("React.").unwrap_or(name.as_str());
215	    // A lib alias that evaluates (`Exclude`, `Extract`, `NonNullable`) is read from TypeScript's own definition.
216	    if !args.is_empty()
217	        && let Some(evaluated) = evaluate_lib_alias(bare, args, consuming_file, ctx, state, depth)
218	    {
219	        return evaluated;
220	    }
221	    if super::is_ts_utility_type(bare)
222	        || matches!(
223	            bare,
224	            // TypeScript primitives used as type names
225	            "object" | "Object" | "Function" | "Symbol" | "BigInt"
226	            // React HTML attribute types (not in is_react_builtin; appear as prop types)
227	            | "HTMLAttributes" | "InputHTMLAttributes" | "TextareaHTMLAttributes"
228	            | "SelectHTMLAttributes" | "ButtonHTMLAttributes" | "AnchorHTMLAttributes"
229	            | "FormHTMLAttributes" | "LabelHTMLAttributes" | "ImgHTMLAttributes"
230	            | "VideoHTMLAttributes" | "AudioHTMLAttributes" | "DOMAttributes"
231	            | "AriaAttributes" | "HTMLInputTypeAttribute" | "HTMLAttributeReferrerPolicy"
232	            | "HTMLAttributeAnchorTarget" | "HTMLInputAutoCompleteAttribute"
233	            // React SVG/generic HTML prop types
234	            | "SVGAttributes" | "SVGProps" | "HTMLProps"
235	            // React component utility types
236	            | "ComponentRef" | "JSXElementConstructor"
237	        )
238	        || bare.ends_with("HTMLAttributes")
239	    {
240	        return PropType::Named { name: name.clone(), args: resolved_args };
241	    }
242	    // DOM element ref types (HTMLDivElement, HTMLInputElement, etc.)
243	    if bare.starts_with("HTML") && bare.ends_with("Element") {
244	        return PropType::Named { name: name.clone(), args: resolved_args };
245	    }
246	    if bare.starts_with("SVG") && bare.ends_with("Element") {
247	        return PropType::Named { name: name.clone(), args: resolved_args };
248	    }
249	
250	    // ── 6.5 Enclosing generic's own type parameter — expected, not unresolvable ─
251	    if !as_declaration && state.has_type_param(bare) {
252	        return PropType::Named { name: unmarked(name).into(), args: resolved_args };
253	    }
254	
255	    // ── 6.7 TypeScript's own ambient globals (Date, RegExp, Element, ...) ────
256	    // Deliberately last: these never go through an import, so nothing earlier
257	    // ever had a reason to look here — but checked only after every other
258	    // shortcut above (including the well-known-TS-utility-type list at step 6)
