1	//! TOON (Token-Optimized Object Notation) renderer for Component Extraction metadata.
2	//!
3	//! Inspired by `michi` (TOON lists and token-optimized agent formatting).
4	//! Formats component props and metadata into a compact, low-token text format
5	//! ideal for LLM prompts, agent context windows, and terminal summaries.
6	//!
7	//! # Lossy by design
8	//!
9	//! TOON is written for a reader that has a token budget, not for a program that reads it back, so it leaves out what
10	//! costs tokens and says little. It carries no `schemaVersion` and has no parser. Compared with the canonical JSON:
11	//!
12	//! - A literal union is never cut, nor is a union with a literal member (`'sm'|'md'|null`): an agent writes a call
13	//!   from those values and cannot guess the missing ones. A union of types only prints at most 8 members, an
14	//!   intersection at most 4 and a layer's `members` at most 24, each followed by `...(+N)` for the rest; the canonical
15	//!   JSON holds every member. A string literal is written in single quotes (`'primary'`), so a member can be told from
16	//!   a type name.
17	//! - A function type prints its parameters with their names (`(value: string, index?: number) => void`); an object or
18	//!   tuple type prints as its source text.
19	//! - A prop's provenance is its `source` only: the name of the type that declared it, not the file or every
20	//!   declaration. Descriptions lose their line breaks.
21	//! - `degradedBy` (a column present only when some prop has it) names why a prop's type is partly `opaque`; a name left
22	//!   as an unexpanded reference is not flagged there, and the diagnostics below say so.
23	//! - A prop's `@deprecated`, `@see` and `@since` tags are written in a `tags` column (present only when some prop has
24	//!   one) as `deprecated=use X;see=https://…;since=2.1`; its other tags, the component's `tags`, `composes`,
25	//!   `notableInherited` and the id tables of the canonical JSON are not written.
26	//! - A discriminated union names its discriminant prop in a `discriminant:` line. Its members' props are merged into
27	//!   one list, each prop's `source` names the member that declares it and each prop absent from some member is
28	//!   optional.
29	
30	use std::fmt::Write;
31	
32	use crate::types::{ComponentEntry, Diagnostic, DiagnosticSeverity, ExtractionOutput, PropType};
33	
34	/// The most names of a collapsed layer's `members` one `inheritance` row lists.
35	const LAYER_MEMBERS_LIMIT: usize = 24;
36	
37	/// The most members a union of types (no literal among them) prints. Real antd props reach 5 members at most in
38	/// 2 of 5049 cases; 8 leaves headroom, and the cut is marked.
39	const UNION_LIMIT: usize = 8;
40	
41	/// The most members an intersection prints.
42	const INTERSECTION_LIMIT: usize = 4;
43	
44	/// The tags of a prop that change how an agent uses it, in the order they are written.
45	const PROP_TAGS: [&str; 3] = ["deprecated", "see", "since"];
46	
47	/// Render a single component's prop table into TOON format.
48	pub fn render_component_toon(entry: &ComponentEntry) -> String {
49	    let mut out = String::new();
50	    writeln!(out, "component:{}:", entry.display_name).ok();
51	    writeln!(out, "  filePath: {}", entry.file_path).ok();
52	    if !entry.description.trim().is_empty() {
53	        writeln!(out, "  description: {}", entry.description.replace('\n', " ")).ok();
54	    }
55	
56	    if let Some(discriminant) = &entry.discriminant_prop {
57	        writeln!(out, "  discriminant: {discriminant}").ok();
58	    }
59	
60	    if !entry.props.is_empty() {
61	        // A column exists only when some prop has something to put in it.
62	        let degraded = entry.props.values().any(|prop| !prop.degraded_by.is_empty());
63	        let degraded_header = if degraded { "degradedBy," } else { "" };
64	        let tagged = entry.props.values().any(|prop| !prop_tags_cell(prop).is_empty());
65	        let tags_header = if tagged { "tags," } else { "" };
66	        writeln!(
67	            out,
68	            "  props[{}] {{name,required,type,default,source,{degraded_header}{tags_header}description}}:",
69	            entry.props.len()
70	        )
71	        .ok();
72	        for (prop_name, prop) in &entry.props {
73	            let req_str = if prop.required { "true" } else { "false" };
74	            let type_str = format_type_compact(&prop.prop_type);
75	            let default_str = prop.default_value.as_ref().map(|d| d.value.as_str()).unwrap_or("");
76	            let source_str = prop.parent.as_ref().map(|parent| parent.name.as_str()).unwrap_or("");
77	            let desc_str = prop.description.replace('\n', " ");
78	
79	            // Format as CSV line: escape strings containing commas or quotes if needed
80	            let degraded_cell =
81	                if degraded { format!("{},", escape_toon_val(&prop.degraded_by.join("|"))) } else { String::new() };
82	            let tags_cell = if tagged { format!("{},", escape_toon_val(&prop_tags_cell(prop))) } else { String::new() };
83	            writeln!(
84	                out,
85	                "    {},{},{},{},{},{}{}{}",
86	                escape_toon_val(prop_name),
87	                req_str,
88	                escape_toon_val(&type_str),
89	                escape_toon_val(default_str),
90	                escape_toon_val(source_str),
91	                degraded_cell,
92	                tags_cell,
93	                escape_toon_val(&desc_str)
94	            )
95	            .ok();
96	        }
97	    }
98	
99	    if !entry.inheritance.is_empty() {
100	        // A collapsed layer lists the names of the props it declares; the column exists only when one does.
101	        let members = entry.inheritance.iter().any(|layer| !layer.members.is_empty());
102	        let members_header = if members { ",members" } else { "" };
103	        writeln!(
104	            out,
105	            "  inheritance[{}] {{typeName,htmlElement,totalProps{members_header}}}:",
106	            entry.inheritance.len()
107	        )
108	        .ok();
109	        for layer in &entry.inheritance {
110	            let elem_str = layer.html_element.as_deref().unwrap_or("none");
111	            let members_cell = if members {
112	                format!(",{}", escape_toon_val(&truncate_with_indicator(&layer.members, LAYER_MEMBERS_LIMIT, "|")))
113	            } else {
114	                String::new()
115	            };
116	            writeln!(
117	                out,
118	                "    {},{},{}{}",
119	                escape_toon_val(&layer.type_name),
120	                escape_toon_val(elem_str),
121	                layer.total_props,
122	                members_cell
123	            )
124	            .ok();
125	        }
126	    }
127	
128	    out
129	}
130	
131	/// One component as an agent reads it: its [`render_component_toon`] table, then the diagnostics that say its props may
132	/// be incomplete (warnings and errors; `info` says nothing about the props), each with its fix when it has one. This is
133	/// the slice a host asks for when it needs one component and not the output of a whole project.
134	pub fn render_component_slice_toon(entry: &ComponentEntry, diagnostics: &[Diagnostic]) -> String {
135	    let mut out = render_component_toon(entry);
136	    let incomplete: Vec<&Diagnostic> =
137	        diagnostics.iter().filter(|diag| diag.severity != DiagnosticSeverity::Info).collect();
138	    if !incomplete.is_empty() {
139	        writeln!(out, "  diagnostics[{}]:", incomplete.len()).ok();
140	        for diag in incomplete {
141	            writeln!(out, "    [{:?}]: {}", diag.severity, diag.message.replace('\n', " ")).ok();
142	            if let Some(help) = &diag.help {
143	                writeln!(out, "      help: {}", help.replace('\n', " ")).ok();
144	            }
145	        }
146	    }
147	    out
148	}
149	
150	/// Render an entire [`ExtractionOutput`] into TOON format.
151	pub fn render_output_toon(output: &ExtractionOutput) -> String {
152	    let mut out = String::new();
153	    if !output.components.is_empty() {
154	        writeln!(out, "docgenComponents[{}]:", output.components.len()).ok();
155	        for entry in output.components.values() {
156	            let comp_toon = render_component_toon(entry);
157	            for line in comp_toon.lines() {
158	                writeln!(out, "  {line}").ok();
159	            }
160	        }
161	    }
162	
163	    if !output.diagnostics.is_empty() {
164	        writeln!(out, "diagnostics[{}]:", output.diagnostics.len()).ok();
165	        for diag in &output.diagnostics {
166	            let file_str = diag.file.as_deref().unwrap_or("unknown");
167	            writeln!(out, "  [{:?}]: {} ({})", diag.severity, diag.message, file_str).ok();
168	            if let Some(help) = &diag.help {
169	                writeln!(out, "    help: {help}").ok();
170	            }
171	            if !diag.affects.is_empty() {
172	                writeln!(out, "    affects: {}", diag.affects.join(", ")).ok();
173	            }
174	        }
175	    }
176	
177	    writeln!(
178	        out,
179	        "stats: extracted={}, parsed={}, cacheHits={}, durationMs={}",
180	        output.stats.components_extracted,
181	        output.stats.files_parsed,
182	        output.stats.dts_cache_hits,
183	        output.stats.duration_ms
184	    )
185	    .ok();
186	
187	    out
188	}
189	
190	/// A prop's `@deprecated`, `@see` and `@since` tags as `deprecated=use X;since=2.1`; a tag with no text is its name
191	/// alone. Empty when the prop has none.
192	fn prop_tags_cell(prop: &crate::types::ParsedProp) -> String {
193	    PROP_TAGS
194	        .iter()
195	        .filter_map(|name| {
196	            let text = prop.tags.get(*name)?.split_whitespace().collect::<Vec<_>>().join(" ");
197	            Some(if text.is_empty() { (*name).to_owned() } else { format!("{name}={text}") })
198	        })
199	        .collect::<Vec<_>>()
200	        .join(";")
201	}
202	
203	/// Truncate `parts` to `limit` items, appending a `"...(+N)"` marker for the
204	/// remainder instead of silently dropping them. Shared by every
205	/// `format_type_compact` branch that renders a bounded member list.
206	fn truncate_with_indicator(parts: &[String], limit: usize, sep: &str) -> String {
207	    if parts.len() <= limit {
208	        return parts.join(sep);
209	    }
210	    let mut shown: Vec<String> = parts[..limit].to_vec();
211	    shown.push(format!("...(+{})", parts.len() - limit));
212	    shown.join(sep)
213	}
214	
215	/// Format a [`PropType`] as a compact string representation for TOON.
216	fn format_type_compact(prop_type: &PropType) -> String {
217	    match prop_type {
218	        PropType::String => "string".into(),
219	        PropType::Number => "number".into(),
220	        PropType::Boolean => "boolean".into(),
221	        PropType::Null => "null".into(),
222	        PropType::Undefined => "undefined".into(),
223	        PropType::Any => "any".into(),
224	        PropType::Never => "never".into(),
225	        PropType::Unknown => "unknown".into(),
226	        PropType::Void => "void".into(),
227	        PropType::StringLiteral(s) => quote_literal(s),
228	        PropType::NumberLiteral(n) => n.to_string(),
229	        PropType::BoolLiteral(b) => b.to_string(),
230	        PropType::LiteralUnion { members, .. } => {
231	            // Every value: it is what an agent writes a valid call from.
232	            members.iter().map(|member| quote_literal(member)).collect::<Vec<_>>().join("|")
233	        }
234	        // The names say what each argument is for (`(value: string)` and not `(string)`), and the markers which
235	        // arguments may be left out (`name?: T`) and which repeat (`...name: T[]`). A destructured parameter has no
236	        // name and prints its type alone.
237	        PropType::Function { params, return_type, .. } => {
238	            let params: Vec<String> = params
239	                .iter()
240	                .map(|p| {
241	                    let ty = format_type_compact(&p.param_type);
242	                    let (rest, optional) = (if p.rest { "..." } else { "" }, if p.optional { "?" } else { "" });
243	                    match &p.name {
244	                        Some(name) => format!("{rest}{name}{optional}: {ty}"),
245	                        None => format!("{rest}{ty}{optional}"),
246	                    }
247	                })
248	                .collect();
249	            format!("({}) => {}", params.join(", "), format_type_compact(return_type))
250	        }
251	        PropType::ReactNode => "ReactNode".into(),
252	        PropType::CssProperties => "CSSProperties".into(),
253	        PropType::ElementType => "ElementType".into(),
254	        PropType::Ref { name, element } => format!("{name}<{}>", element.as_deref().unwrap_or("unknown")),
255	        PropType::Readonly(inner) => match &**inner {
256	            PropType::Array(element_type) => format!("ReadonlyArray<{}>", format_type_compact(element_type)),
257	            other => format!("readonly {}", format_type_compact(other)),
258	        },
259	        PropType::Object(_) => prop_type.raw_string(),
260	        PropType::Array(element_type) => format!("Array<{}>", format_type_compact(element_type)),
261	        PropType::Tuple(_) => prop_type.raw_string(),
262	        PropType::Union(members) => {
263	            let formatted: Vec<String> = members.iter().map(format_type_compact).collect();
264	            // A literal among the members is a value an agent may write: show every one. Only a union of types is cut.
265	            let has_literal = members.iter().any(|member| {
266	                matches!(
267	                    member,
268	                    PropType::StringLiteral(_)
269	                        | PropType::NumberLiteral(_)
270	                        | PropType::BoolLiteral(_)
271	                        | PropType::LiteralUnion { .. }
272	                )
273	            });
274	            if has_literal { formatted.join("|") } else { truncate_with_indicator(&formatted, UNION_LIMIT, "|") }
275	        }
276	        PropType::Intersection(members) => {
277	            let formatted: Vec<String> = members.iter().map(format_type_compact).collect();
278	            truncate_with_indicator(&formatted, INTERSECTION_LIMIT, "&")
279	        }
280	        PropType::HtmlAttributes { element, .. } => format!("HTMLAttributes<{element}>"),
281	        PropType::Named { name, args } => {
282	            if args.is_empty() {
283	                name.to_string()
284	            } else {
285	                let formatted_args: Vec<String> = args.iter().map(format_type_compact).collect();
286	                format!("{name}<{}>", formatted_args.join(", "))
287	            }
288	        }
289	        PropType::SxProps => "SxProps".into(),
290	        PropType::Opaque(detail) => format!("opaque({})", detail.raw()),
291	    }
292	}
293	
294	/// A string literal in single quotes, so `'primary'` is a value and `primary` a type name. A quote inside it is escaped.
295	fn quote_literal(value: &str) -> String {
296	    format!("'{}'", value.replace('\\', "\\\\").replace('\'', "\\'"))
297	}
298	
299	/// Escape a TOON field value if it contains commas, newlines, or quotes.
300	fn escape_toon_val(val: &str) -> String {
301	    if val.contains(',') || val.contains('\n') || val.contains('"') {
302	        format!("\"{}\"", val.replace('"', "\\\"").replace('\n', " "))
303	    } else {
304	        val.to_string()
305	    }
306	}
