        | PropType::Intersection(_)
        | PropType::Array(_)
        | PropType::Tuple(_)
        | PropType::Readonly(_)
        | PropType::Object(_)
        | PropType::Callable { .. }
        | PropType::Named { .. }
        | PropType::Recursive { .. }
        | PropType::Truncated { .. }
        | PropType::ReactNode
        | PropType::CssProperties
        | PropType::Function { .. }
        | PropType::Ref { .. }
